extends CharacterBody2D
class_name Player

var inventory: Inventory = Inventory.new()
var health: int = 100

func _ready():
  inventory.add_item(Pokeball.new())

func use_item(item_id: int):
  inventory.use(item_id)

extends Resource
class_name Inventory

var items: Array[Item] = []

func add_item(item: Item):
  items.append(item)

func use(id: int):
  if id < items.size():
    items[id].apply()
    items.remove_at(id)
